const DAY_MS = 24 * 60 * 60 * 1000;

function addDays(date, days) {
  return new Date(Date.parse(date + "T00:00:00Z") + days * DAY_MS).toISOString().slice(0, 10);
}

function isActive(feed, service, date) {
  const override = (feed.exceptions ?? []).find(x => x.service === service && x.date === date);
  if (override) return override.active;
  return (feed.calendar[service] ?? []).includes(date);
}

// A service date owns its whole timetable: clocks below 24:00 run on that
// civil date, and clocks at or above 24:00 run on the following civil date.
// The query window can therefore contain departures from both the previous
// service date (late-night trips) and the window's own service dates.
export function departures(feed, stop, start, minutes) {
  const from = Date.parse(start);
  const until = from + minutes * 60000;
  const firstDate = new Date(from).toISOString().slice(0, 10);
  const lastDate = new Date(until).toISOString().slice(0, 10);

  // A trip departs on its service date, or one civil date later when its
  // clock is >= 24:00. Starting one day before the window is thus sufficient
  // to catch late-night services that continue past midnight.
  const serviceDates = [];
  for (let date = addDays(firstDate, -1); date <= lastDate; date = addDays(date, 1)) {
    serviceDates.push(date);
  }

  const rows = [];
  for (const trip of feed.trips) {
    if (trip.stop !== stop) continue;
    const [h, m, s] = trip.clock.split(":").map(Number);
    const clockMs = 1000 * (3600 * h + 60 * m + s);
    for (const serviceDate of serviceDates) {
      if (!isActive(feed, trip.service, serviceDate)) continue;
      const time = Date.parse(serviceDate + "T00:00:00Z") + clockMs;
      if (time >= from && time < until) {
        rows.push({tripId: trip.tripId, serviceDate, departure: new Date(time).toISOString()});
      }
    }
  }

  return rows.sort((a, b) => {
    if (a.departure !== b.departure) return a.departure < b.departure ? -1 : 1;
    if (a.tripId !== b.tripId) return a.tripId < b.tripId ? -1 : 1;
    return 0;
  });
}

import test from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {departures} from "./board.mjs";
const feed=JSON.parse(readFileSync(new URL("./feed.json",import.meta.url)));

test("weekday noon departure",()=>assert.deepEqual(departures(feed,"River","2025-07-04T12:00:00Z",5).map(r=>r.tripId),["D1"]));

// DB-17: at Saturday 00:00 the board must show both Friday's late-night
// service (R7, a 24:12 clock owned by Friday) and Saturday's own extra
// service (X3). SAT's regular S1 trip is cancelled by an exception.
test("Saturday 00:00 shows Friday's last bus and Saturday's extra",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-05T00:00:00Z",30),[
    {tripId:"R7",serviceDate:"2025-07-04",departure:"2025-07-05T00:12:00.000Z"},
    {tripId:"X3",serviceDate:"2025-07-05",departure:"2025-07-05T00:19:00.000Z"},
  ]);
});

test("Saturday's own extra service is not moved to Friday",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-05T00:15:00Z",5),[
    {tripId:"X3",serviceDate:"2025-07-05",departure:"2025-07-05T00:19:00.000Z"},
  ]);
});

test("Friday evening window still sees the post-midnight last bus",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-04T23:55:00Z",30).map(r=>r.tripId),["R7","X3"]);
});

test("cancelled service on its own service date stays hidden",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-05T00:07:00Z",2),[]);
});

test("late-night expansion also applies to other stops",()=>{
  assert.deepEqual(departures(feed,"East","2025-07-05T00:00:00Z",15),[
    {tripId:"E2",serviceDate:"2025-07-04",departure:"2025-07-05T00:10:00.000Z"},
  ]);
});

test("window is left-closed and right-open",()=>{
  assert.deepEqual(departures(feed,"River","2025-07-05T00:12:00Z",7).map(r=>r.tripId),["R7"]);
  assert.deepEqual(departures(feed,"River","2025-07-05T00:00:00Z",12),[]);
});

